fter":{"type":"string"},"query":{"maxLength":200,"type":"string"}},"type":"object"}},"type":"function"},{"function":{"description":"Change your own avatar only when the user requests it. Use a sent image or generated image ID from this private conversation, or null to remove. Static PNG/JPEG/WebP up to 4 MiB and 16 megapixels; cropped to 256x256 PNG. Supply the avatar revision from system context. A conflict requires new user guidance, never overwrite their newer choice. Completed changes survive cancellation.","name":"set_avatar","parameters":{"additionalProperties":false,"properties":{"image":{"type":["string","null"]},"revision":{"minimum":0,"type":"integer"}},"required":["image","revision"],"type":"object"}},"type":"function"},{"function":{"description":"List your own local static sites, ten per page. These URLs are local to this running server, not internet publication. Use current revision to replace or delete. No access to other agents.","name":"list_sites","parameters":{"additionalProperties":false,"properties":{"after":{"type":"string"}},"type":"object"}},"type":"function"},{"function":{"description":"Delete your own local site only when requested by the user. Supply current revision from list_sites. Clears stored HTML and disables its URL; completed deletion survives cancellation.","name":"delete_site","parameters":{"additionalProperties":false,"properties":{"revision":{"minimum":1,"type":"integer"},"site":{"type":"string"}},"required":["site","revision"],"type":"object"}},"type":"function"},{"function":{"description":"Read your own saved provider account ID, model, backup model and profile revision. Reports configuration only, not provider health. No credentials or endpoint URLs. Does not change settings.","name":"read_provider_settings","parameters":{"additionalProperties":false,"properties":{},"type":"object"}},"type":"function"},{"function":{"description":"Change your own saved name, role or instructions only when the user requests it. Supply current profile revision from system context and at least one changed field. Omitted fields stay unchanged. Future executions use the new instructions; this execution keeps its existing context. Cannot change model, account, permissions or other agents. Conflict requires new user guidance. Completed changes survive cancellation.","name":"edit_profile","parameters":{"additionalProperties":false,"properties":{"instructions":{"maxLength":8000,"type":"string"},"name":{"maxLength":80,"type":"string"},"revision":{"minimum":1,"type":"integer"},"role":{"maxLength":60,"type":"string"}},"required":["revision"],"type":"object"}},"type":"function"},{"function":{"description":"List ten currently enabled skills installed for you, with pinned versions. Use next_after to continue. Private conversations only; does not change installations.","name":"list_skills","parameters":{"additionalProperties":false,"properties":{"after":{"type":"string"}},"type":"object"}},"type":"function"},{"function":{"description":"Read the currently enabled, installed version of one of your skills. Library versions and other agents are inaccessible. Does not change installations.","name":"read_skill","parameters":{"additionalProperties":false,"properties":{"id":{"type":"string"}},"required":["id"],"type":"object"}},"type":"function"},{"function":{"description":"Read a supporting text file from your enabled pinned skill, in 8000-character pages. Get exact paths from read_skill. Files are immutable imported snapshots, not host filesystem access. Cannot execute scripts. Private conversations only.","name":"read_skill_file","parameters":{"additionalProperties":false,"properties":{"id":{"type":"string"},"offset":{"minimum":0,"type":"integer"},"path":{"maxLength":240,"type":"string"}},"required":["id","path"],"type":"object"}},"type":"function"},{"function":{"description":"List ten routines owned by you, ordered by ID. Use next_after to continue. Does not run or change routines. Available only in private conversations.",